# Directory tree traversal: DFS and BFS over a nested directory mapping.
tree = {'docs': {'a.txt': None, 'sub': {'b.txt': None}}, 'img': {'c.png': None}}
def dfs(node, path=""):
    out = []
    for name, sub in sorted(node.items()):
        p = path + "/" + name
        out.append(p)
        if isinstance(sub, dict):
            out += dfs(sub, p)
    return out
def bfs(node):
    out, queue = [], [("", node)]
    while queue:
        path, cur = queue.pop(0)
        for name, sub in sorted(cur.items()):
            p = path + "/" + name
            out.append(p)
            if isinstance(sub, dict):
                queue.append((p, sub))
    return out
mode = "dfs"
paths = dfs(tree) if mode == "dfs" else bfs(tree)
print(mode.upper(), "order:")
for p in paths[:8]:
    print(" ", p)
print("total entries:", len(paths))

